    // Make an AI fighter object from ALL_CHARS template    // Make an AI fighter object from ALL_CHARS template     makeAIFighter(template, rng, orgId, age) {       const notion = {pw:template.pw,sp:template.sp,te:template.te,st:template.st,mn:template.mn};       const trainCap = Engine.rival.generateTrainCap(rng, notion, template.pot);       // AI fighters start closer to their Notion values (established pros)       const maturity = Math.min(1.0, 0.70 + (age - 17) * 0.04 + Engine.rng.float(rng) * 0.10);       const current = {};       ['pw','sp','te','st','mn'].forEach(s => {         current[s] = Math.min(trainCap[s], Math.round(notion[s] * maturity));       });       const ovr = Math.round((current.pw+current.sp+current.te+current.st+current.mn)/5);       // Calculate assessed value (pricing-balance-spec 繝ｻ繧托ｽｽ・ｧ1)       const charForAssess = { ...current, pot: template.pot, trainCap };       const av = Engine.scout.calcAssessedValue(charForAssess, rng, 1);       const durability = Engine.career.generateDurability(rng);       // 髯具ｽｻ隴弱・・Цear髣皮甥ﾂ繝ｻ・ｽ・ｸ郢晢ｽｻ decayStartAge鬮ｮ諛翫・郢晢ｽｻ鬯ｩ蛹・ｽｽ・ｸ髫ｰ繝ｻ・ｹ譏ｶ繝ｻ驍ｵ・ｺ繝ｻ・ｯwear鬮｣・｢郢晢ｽｻ繝ｻ・ｩ髢ｧ・ｴ繝ｻ・ｸ陋ｹ・ｻ遶擾ｽｩ驍ｵ・ｺ繝ｻ・ｨ驍ｵ・ｺ陷会ｽｱ遯ｶ・ｻ鬨ｾ蠅難ｽｻ阮吶・       const effectiveAge = age || (17 + Engine.rng.int(rng, 0, 11));       const aiInitDecayStart = 23 + (durability || 0);       let initWear = 0;       if (effectiveAge >= aiInitDecayStart) {         const yearsOfWear = effectiveAge - aiInitDecayStart;         initWear = yearsOfWear * (8 + Engine.rng.int(rng, -3, 3));         initWear = Math.min(79, Math.max(0, initWear));       }       return {         id: template.id, name: template.name, h: template.h,         pw: current.pw, sp: current.sp, te: current.te, st: current.st, mn: current.mn,         style: template.style, role: template.role, pot: { ...template.pot },         traits: template.traits || [],         personality: template.personality || 'normal',         archetype: template.archetype || 'normal',         notionValue: notion, trainCap,         popularity: Math.max(5, Math.round(ovr * 0.6 + Engine.rng.int(rng, -5, 10))),         orgId, age: effectiveAge,         careerSeasons: Math.max(0, (effectiveAge - 17)),         condition: 70 + Engine.rng.int(rng, 0, 19),         losingStreak: 0, preInjuryPop: null,         assessedValue: av.assessedValue, assessedTier: av.assessedTier,         assessedVariance: av.assessedVariance, assessedSeason: av.assessedSeason,         // AI鬩搾ｽｨ繝ｻ・ｱ髣包ｽｳ・つ髫ｰ謔滂ｽｮ・｣髢ｨ繝ｻPhase2: processAIWeek驍ｵ・ｺ繝ｻ・ｫ髯滂ｽ｢郢晢ｽｻ繝ｻ・ｦ遶丞｣ｺ繝ｻ驛｢譎・ｽｼ譁絶襖驛｢譎｢・ｽ・ｼ驛｢譎｢・ｽ・ｫ驛｢譎∵ｭ薙・・｣隲幢ｽｷ繝ｻ・ｮ郢晢ｽｻ        schedule: 'balance',         wins: 0, losses: 0, draws: 0,         injury: null,         seasonGrowth: { pw: 0, sp: 0, te: 0, st: 0, mn: 0 },         intensive: false,         intensiveWeeks: 0,         lastMatchResult: null,         careerRecord: Engine.career.createRecord(),         durability,         wear: initWear,         seasonInjuries: 0,         careerHistory: [],         growthPenalty: null,         trust: 50,         promoStack: 0,     // 驛｢譎丞ｹｲ・取ｺｽ・ｹ譎｢・ｽ・｢髫ｰ・ｾ繝ｻ・ｹ髣厄ｽｫ繝ｻ・ｮ v1.0: 鬮ｫ・ｧ繝ｻ・ｦ髯ｷ・ｷ闔・･霎ｯ諷包ｽｹ譎丞ｹｲ・取ｺｽ・ｹ譎｢・ｽ・｢鬮｣・｢郢晢ｽｻ繝ｻ・ｩ郢晢ｽｻ0驍ｵ・ｲ郢晢ｽｻ         lastTitleShowWeek: 0,  // Phase 2: 驛｢・ｧ繝ｻ・ｿ驛｢・ｧ繝ｻ・､驛｢譎冗樟・取凵・ｬ魃会ｽｽ・ｦ髯ｷ繝ｻ・ｽ・ｺ髯懶ｽ｣繝ｻ・ｴ鬯ｨ・ｾ繝ｻ・ｱ鬮ｴ謇假ｽｽ・ｽ鬮ｴ謳ｾ・ｽ・｡         orgJoinWeek: 0,      // Phase 3: 髯懈圜・ｽ・｣髣厄ｽｴ霓｣莨懊・髯ｷ闌ｨ・ｽ・･髫ｴ蠑ｱ・・ｹ晢ｽｻ鬩搾ｽｨ繝ｻ・ｶ髯昴・・ｽ・ｾ鬯ｨ・ｾ繝ｻ・ｱ         orgTimeline: [{ orgId: orgId || 'fa', fromSeason: 1, fromWeek: 1 }],       };     },     // Initialize all AI org rosters from ORG_ASSIGN     // 髫ｨ貂可髫ｨ貂可 Roster Randomization: assign ALL_CHARS to S/A/B/FA/dormant 髫ｨ貂可髫ｨ貂可     initRandomRoster(rng) {       const cfg = ROSTER_CFG;       // Step 1: Compute potTotal for all characters       const chars = ALL_CHARS.map(c => {         const potTotal = (c.pot.pw||0) + (c.pot.sp||0) + (c.pot.te||0) + (c.pot.st||0) + (c.pot.mn||0);         let tierClass;         if (potTotal >= cfg.superEliteThreshold) tierClass = 'superElite';         else if (potTotal >= cfg.eliteThreshold) tierClass = 'elite';         else tierClass = 'other';         return { id: c.id, potTotal, tierClass, group: CHAR_GROUP[c.id] || 'other' };       });        // Step 2: Super-elite 驕ｶ鄙ｫ繝ｻS鬩堺ｸ橸ｽ､繧托ｽｽ・｢繝ｻ・ｺ髯橸ｽｳ郢晢ｽｻ      const superElites = chars.filter(c => c.tierClass === 'superElite');       const remaining = chars.filter(c => c.tierClass !== 'superElite');        // Step 3: Shuffle remaining with seeded RNG       const shuffled = seededShuffle(remaining, rng);        // Helper: weighted pick with series bonus       // potWeight: how strongly potTotal influences selection (0=random, 1=strongly)       // minPotTotal: minimum potTotal to be eligible (0=no filter)       function weightedPick(pool, orgMembers, count, maxElites, potWeight, minPotTotal) {         const result = [];         let eliteCount = 0;         const available = [...pool];         while (result.length < count && available.length > 0) {           // Calculate weights           const weights = available.map(c => {             // Elite cap check             if (c.tierClass === 'elite' && eliteCount >= maxElites) return 0;             // Minimum potTotal filter             if (minPotTotal && c.potTotal < minPotTotal) return 0;             // Base weight             let w = 1.0;             // PotTotal influence (scaled by potWeight parameter)             // potTotal range ~440-820, normalize to 0-1 then scale             w += (c.potTotal / 800) * (potWeight || 0);             // Series bonus: if same group already in org             if (c.group !== 'other' && orgMembers.some(m => m.group === c.group)) {               w += cfg.seriesBonus;             }             return w;           });           // Weighted random selection           const totalWeight = weights.reduce((s, w) => s + w, 0);           if (totalWeight <= 0) break;           let roll = Engine.rng.float(rng) * totalWeight;           let picked = -1;           for (let i = 0; i < available.length; i++) {             roll -= weights[i];             if (roll <= 0) { picked = i; break; }           }           if (picked < 0) picked = 0;           const chosen = available.splice(picked, 1)[0];           if (chosen.tierClass === 'elite') eliteCount++;           result.push(chosen);           orgMembers.push(chosen);         }         // Remove picked from pool         const resultIds = new Set(result.map(r => r.id));         for (let i = pool.length - 1; i >= 0; i--) {           if (resultIds.has(pool[i].id)) pool.splice(i, 1);         }         return result;       }        // Step 4: Fill S鬩堺ｸ翫・(superElites + elite top3 guaranteed + fill remaining)       // 3c: S鬩堺ｸ橸ｽ｣・ｹ遶雁・lite髣包ｽｳ髮榊・・ｽ・ｽ郢晢ｽｻ髯ｷ・ｷ鬮ｦ・ｪ繝ｻ蟶晢ｿ｡繝ｻ・ｺ髯橸ｽｳ陞溯・繝ｻ鬩励ｑ・ｽ・ｮ       const elitesSorted = shuffled         .filter(c => c.tierClass === 'elite')         .sort((a, b) => b.potTotal - a.potTotal);       const guaranteedElites = elitesSorted.slice(0, 3);       const guaranteedIds = new Set(guaranteedElites.map(c => c.id));        const sMembers = [...superElites, ...guaranteedElites];       const sRemaining = cfg.org_s - sMembers.length;       // Sort pool by potTotal desc for S-tier (strongest first)       // pool驍ｵ・ｺ闕ｵ譎｢・ｽ譖ｳuaranteed髯具ｽｻ郢晢ｽｻ繝ｻ蟶晢ｽｫ・ｯ繝ｻ・､髯樊ｺ倥・      shuffled.sort((a, b) => b.potTotal - a.potTotal);       const pool = shuffled.filter(c => !guaranteedIds.has(c.id));       const sPicked = weightedPick(pool, sMembers, sRemaining, 99, 3.0, 720); // S: strong potTotal bias, 髫ｴ蟶ｷ蛻､隰泌ｴ手р繝ｻ・･髣包ｽｳ驗呻ｽｫ郢晢ｽｻ驍ｵ・ｺ繝ｻ・ｿ       const sAll = [...sMembers.map(c => c.id), ...sPicked.map(c => c.id)];        // Step 5: Re-shuffle remaining pool for A/B (reset sorting)       const poolForAB = seededShuffle(pool, rng);       pool.length = 0;       pool.push(...poolForAB);        // Step 6: Fill A鬩堺ｸ翫・(max 3 elites 驕ｯ・ｶ郢晢ｽｻAI_TIER_LIMITS)       // AI鬩搾ｽｨ繝ｻ・ｱ髣包ｽｳ・つ髫ｰ謔滂ｽｮ・｣髢ｨ繝ｻ繝ｻ繧托ｽｽ・ｧ4.3: A鬩堺ｸ橸ｽ｣・ｹ遶雁・lite髣比ｼ夲ｽｽ・･髣包ｽｳ郢晢ｽｻ髯ｷ・ｷ鬮ｦ・ｪ繝ｻ螳壼ｰ・ｭ弱・・ｽ・ｨ繝ｻ・ｼ       const aMembers = [];       const eliteInPool = pool.filter(c => c.tierClass === 'elite');       if (eliteInPool.length > 0) {         // elite驛｢譎丞ｹｲ郢晢ｽｻ驛｢譎｢・ｽ・ｫ驍ｵ・ｺ闕ｵ譎｢・ｽ繝ｻ髯ｷ・ｷ鬮ｦ・ｪ繝ｻ菴・ｩ堺ｸ橸ｽ｣・ｹ遶企ｦｴ・｡繝ｻ・ｺ髯橸ｽｳ陞溯・繝ｻ鬩励ｑ・ｽ・ｮ         const eliteIdx = pool.indexOf(eliteInPool[0]);         const guaranteed = pool.splice(eliteIdx, 1)[0];         aMembers.push(guaranteed);       }       const aRemaining = cfg.org_a - aMembers.length;       const aPicked = weightedPick(pool, aMembers, aRemaining, (AI_TIER_LIMITS.A || {}).maxProdigies || 3, 1.0, 640);       const aAll = aMembers.map(c => c.id);        // Step 7: Fill B鬩堺ｸ翫・(max 1 elite 驕ｯ・ｶ郢晢ｽｻAI_TIER_LIMITS)       const bMembers = [];       const bPicked = weightedPick(pool, bMembers, cfg.org_b, (AI_TIER_LIMITS.B || {}).maxProdigies || 1, 0.3);       const bAll = bPicked.map(c => c.id);        // Step 8: Remaining 驕ｶ鄙ｫ繝ｻFA (cfg.fa slots) + dormant (rest)       const faShuffled = seededShuffle(pool, rng);       const faAll = faShuffled.slice(0, cfg.fa).map(c => c.id);       const dormantAll = faShuffled.slice(cfg.fa).map(c => c.id);        // Step 9: Write to ORG_ASSIGN       ORG_ASSIGN.org_s = sAll;       ORG_ASSIGN.org_a = aAll;       ORG_ASSIGN.org_b = bAll;       ORG_ASSIGN.free = faAll;       ORG_ASSIGN.player = [];        return { dormantPool: dormantAll };     },      initAIOrgs(rng) {       const nameMap = {};       RIVAL_ORGS.forEach(org => {         const pool = RIVAL_ORG_NAME_POOL[org.tier];         if (pool && pool.length) {           const idx = Engine.rng.int(rng, 0, pool.length - 1);           org.name = pool[idx];           nameMap[org.id] = org.name;         }       });        const orgs = {};       RIVAL_ORGS.forEach(org => {         const ids = ORG_ASSIGN[org.id] || [];         const roster = ids.map(id => {           const t = ALL_CHARS.find(c => c.id === id);           if (!t) return null;           return Engine.rival.makeAIFighter(t, rng, org.id, 17 + Engine.rng.int(rng, 0, 11));         }).filter(Boolean);         roster.sort((a, b) => Engine.util.ov(b) - Engine.util.ov(a));         roster.forEach((f, i) => {           const tierBonus = { S: 14, A: 4, B: 1 }[org.tier] || 0;           if (i === 0) f.popularity = Math.min(90, f.popularity + 15 + tierBonus);           else if (i < 3) f.popularity = Math.min(85, f.popularity + 8 + tierBonus);           else if (i < 6) f.popularity = Math.min(75, f.popularity + 3 + tierBonus);         });         orgs[org.id] = {           roster,           orgPop: { S: 75, A: 55, B: 35 }[org.tier] || 30,           lockerRoomMorale: 60,           coaches: [],           coachAssign: {},         };       });       return { aiOrgs: Engine.rival.ensureAICoachStaffing(rng, orgs), rivalOrgNames: nameMap };     },     /** Restore org names from saved state */     applyOrgNames(nameMap) {       if (!nameMap) return;       RIVAL_ORGS.forEach(org => {         if (nameMap[org.id]) org.name = nameMap[org.id];       });     },     // Get dormant IDs (chars not assigned to any org or free)     getDormantIds() {       const assigned = new Set();       Object.values(ORG_ASSIGN).forEach(ids => ids.forEach(id => assigned.add(id)));       return ALL_CHARS.filter(c => !assigned.has(c.id)).map(c => c.id);     },     // Utility: get merged AI org info (config + state) by orgId     getOrgInfo(aiOrgs, orgId) {       const cfg = RIVAL_ORGS.find(o => o.id === orgId);       const data = aiOrgs && aiOrgs[orgId];       if (!cfg || !data) return null;       return {         id: cfg.id,         orgId: cfg.id,         name: cfg.name,         tier: cfg.tier,         coachMul: cfg.coachMul,         roster: data.roster,         orgPop: data.orgPop,         coaches: data.coaches || [],         coachAssign: data.coachAssign || {},         lockerRoomMorale: data.lockerRoomMorale,         titles: data.titles || {},       };     },     // Utility: get all AI orgs as array with merged config+state     getAllOrgs(aiOrgs) {       return RIVAL_ORGS.map(cfg => Engine.rival.getOrgInfo(aiOrgs, cfg.id)).filter(Boolean);     },     dedupeRoster(roster) {       const seen = new Set();       const unique = [];       (roster || []).forEach(f => {         if (!f || seen.has(f.id)) return;         seen.add(f.id);         unique.push(f);       });       return unique;     },     pushUniqueFighter(roster, fighter) {       if (!fighter) return roster || [];       const target = Array.isArray(roster) ? roster : [];       if (target.some(f => f && f.id === fighter.id)) return target;       target.push(fighter);       return target;     },     sanitizeAIOrgs(aiOrgs) {       if (!aiOrgs) return aiOrgs;       const sanitized = {};       Object.keys(aiOrgs).forEach(orgId => {         const org = aiOrgs[orgId];         sanitized[orgId] = org ? {           ...org,           roster: Engine.rival.dedupeRoster(org.roster || []),           coaches: Array.isArray(org.coaches) ? [...org.coaches] : [],           coachAssign: { ...(org.coachAssign || {}) },         } : org;       });       return sanitized;     },      buildAIState(baseState, orgData, roster, tier) {       const fallbackTier = tier || 'B';       const data = orgData || {};       return {         ...baseState,         roster: roster || data.roster || [],         titles: data.titles || {},         coaches: Array.isArray(data.coaches) ? [...data.coaches] : [],         coachAssign: { ...(data.coachAssign || {}) },         orgPop: data.orgPop != null ? data.orgPop : ({ S: 75, A: 55, B: 35 }[fallbackTier] || 30),         lockerRoomMorale: data.lockerRoomMorale != null ? data.lockerRoomMorale : 60,         funds: data.funds != null ? data.funds : Engine.rival._estimateAIFunds(fallbackTier),       };     },      _getAICoachPlan(tier) {       const plan = AI_COACH_STAFFING[tier] || AI_COACH_STAFFING.B || { grades: [] };       return [...(plan.grades || [])];     },      _getAICoachGradeOrder(targetGrade) {       if (targetGrade === 'A') return ['A', 'B', 'C'];       if (targetGrade === 'B') return ['B', 'C', 'A'];       return ['C', 'B', 'A'];     },      _pickAICoachId(rng, targetGrade, usedCoachIds, orgPop) {       const gradeOrder = Engine.rival._getAICoachGradeOrder(targetGrade);       let best = null;       gradeOrder.forEach((grade, idx) => {         ALL_COACHES.filter(coach => {           if (usedCoachIds.has(coach.id)) return false;           if (coach.grade !== grade) return false;           return (orgPop || 0) >= (coach.minOrgPop || 0);         }).forEach(coach => {           const traitDef = COACH_TRAIT_DEFS[coach.trait] || {};           let score = 100 - (idx * 18);           score += (COACH_RANKS[coach.teaching] || 1) * 10;           if (coach.style === 'Allround') score += 2;           if (traitDef.growthMult) score += 6;           if (traitDef.matchGrowthBonus) score += 5;           if ((traitDef.condDrain || 0) < 0) score += 4;           if ((traitDef.injuryMult || 1) < 1) score += 3;           if (traitDef.mqBonus) score += 4;           if (traitDef.decayReduction) score += 2;           if (traitDef.scoutBonus) score -= 8;           score += Engine.rng.float(rng);           if (!best || score > best.score) best = { id: coach.id, score };         });       });       return best ? best.id : null;     },      _getAIFighterDevelopmentScore(fighter) {       const capSource = fighter.trainCap || fighter.pot || {};       const stats = ['pw', 'sp', 'te', 'st', 'mn'];       const avgCap = stats.reduce((sum, stat) => sum + (capSource[stat] || fighter[stat] || 50), 0) / stats.length;       return (Engine.util.ov(fighter) * 0.7) + (avgCap * 0.3);     },      _getAIFighterCoachFit(fighter, coach) {       if (!fighter || !coach) return -Infinity;       const traitDef = COACH_TRAIT_DEFS[coach.trait] || {};       const capSource = fighter.trainCap || fighter.pot || {};       const remaining = ['pw', 'sp', 'te', 'st'].reduce((sum, stat) => {         const cap = capSource[stat] || fighter[stat] || 0;         return sum + Math.max(0, cap - (fighter[stat] || 0));       }, 0) / 4;       let score = Engine.rival._getAIFighterDevelopmentScore(fighter);       if (coach.style === fighter.style) score += 8;       else if (coach.style === 'Allround') score += 4;       if (traitDef.growthMult) score += (fighter.age || 99) <= 21 ? 6 : 2;       if (traitDef.matchGrowthBonus) score += Engine.util.ov(fighter) >= 55 ? 5 : 2;       if ((traitDef.condDrain || 0) < 0 || (traitDef.injuryMult || 1) < 1) {         score += Math.max(0, 80 - (fighter.condition || 70)) * 0.08;       }       if (traitDef.mqBonus) score += (fighter.popularity || 0) >= 40 ? 3 : 1;       if (traitDef.decayReduction) score += (fighter.age || 17) >= 27 ? 5 : 0;       if (traitDef.scoutBonus) score -= 6;       score += remaining * 0.08;       return score;     },      buildAICoachAssignments(roster, coachIds) {       const coaches = (coachIds || []).map(id => ALL_COACHES.find(c => c.id === id)).filter(Boolean);       if (coaches.length === 0) return {};        const orderedRoster = [...(roster || [])].sort((a, b) => (         Engine.rival._getAIFighterDevelopmentScore(b) - Engine.rival._getAIFighterDevelopmentScore(a)       ));       const loads = new Map(coaches.map(coach => [coach.id, 0]));       const coachAssign = {};        orderedRoster.forEach(fighter => {         let bestCoach = null;         let bestScore = -Infinity;         coaches.forEach(coach => {           const currentLoad = loads.get(coach.id) || 0;           if (currentLoad >= COACH_MAX_ASSIGN) return;           const fitScore = Engine.rival._getAIFighterCoachFit(fighter, coach) - (currentLoad * 3);           if (fitScore > bestScore) {             bestCoach = coach;             bestScore = fitScore;           }         });         if (!bestCoach) return;         if (!coachAssign[bestCoach.id]) coachAssign[bestCoach.id] = [];         coachAssign[bestCoach.id].push(fighter.id);         loads.set(bestCoach.id, (loads.get(bestCoach.id) || 0) + 1);       });        return coachAssign;     },      ensureAICoachStaffing(rng, aiOrgs, reservedCoachIds = []) {       if (!aiOrgs) return aiOrgs;       const sanitized = Engine.rival.sanitizeAIOrgs(aiOrgs);       const usedCoachIds = new Set(reservedCoachIds || []);       const next = {};       const tierOrder = { S: 0, A: 1, B: 2 };       const sortedOrgs = [...RIVAL_ORGS].sort((a, b) => tierOrder[a.tier] - tierOrder[b.tier]);        sortedOrgs.forEach(cfg => {         const current = sanitized[cfg.id] || {};         const currentCoaches = (current.coaches || []).map(id => ALL_COACHES.find(c => c.id === id)).filter(Boolean);         const keepPool = [...currentCoaches];         const selected = [];         const plan = Engine.rival._getAICoachPlan(cfg.tier);         const orgPop = current.orgPop != null ? current.orgPop : ({ S: 75, A: 55, B: 35 }[cfg.tier] || 30);          plan.forEach(targetGrade => {           const keepIdx = keepPool.findIndex(coach => coach.grade === targetGrade && !usedCoachIds.has(coach.id));           if (keepIdx >= 0) {             const kept = keepPool.splice(keepIdx, 1)[0];             selected.push(kept.id);             usedCoachIds.add(kept.id);             return;           }           const pickedId = Engine.rival._pickAICoachId(rng, targetGrade, usedCoachIds, orgPop);           if (pickedId != null) {             selected.push(pickedId);             usedCoachIds.add(pickedId);           }         });          const roster = Engine.rival.dedupeRoster(current.roster || []);         next[cfg.id] = {           ...current,           roster,           orgPop,           lockerRoomMorale: current.lockerRoomMorale != null ? current.lockerRoomMorale : 60,           coaches: selected,           coachAssign: Engine.rival.buildAICoachAssignments(roster, selected),         };       });        Object.keys(sanitized).forEach(orgId => {         if (!next[orgId]) next[orgId] = sanitized[orgId];       });       return next;     },     // Check if current week is a transfer window     isTransferWindow(week) {       return TRANSFER_CONFIG.windows.includes(week);     },     // Calculate transfer fee (rival-org 繝ｻ繧托ｽｽ・ｧ7.1)     calcTransferFee(fighter, fromOrgTier) {       const ovr = Engine.util.ov(fighter);       const popBonus = (fighter.popularity || 0) * 10;       let baseFee;       if (ovr >= 80)      baseFee = 800;       else if (ovr >= 60) baseFee = 400;       else if (ovr >= 45) baseFee = 200;       else                baseFee = 100;       const tierMul = {S:1.5, A:1.2, B:1.0}[fromOrgTier] || 1.0;       return Math.round((baseFee + popBonus) * tierMul);     },      // 髫ｨ貂可髫ｨ貂可 AI鬩搾ｽｨ繝ｻ・ｱ髣包ｽｳ・つ髫ｰ謔滂ｽｮ・｣髢ｨ繝ｻPhase3+4: AI鬯ｨ・ｾ繝ｻ・ｱ髫ｹ・ｺ繝ｻ・｡髯ｷ繝ｻ・ｽ・ｦ鬨ｾ繝ｻ繝ｻ髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可     // AI髯懈圜・ｽ・｣髣厄ｽｴ髦ｮ蜷ｶ繝ｻ鬯ｩ蛹・ｽｽ・ｸ髫ｰ繝ｻ・ｹ譏ｶ繝ｻ驛｢譎丞ｹｲ・取ｨ抵ｽｹ・ｧ繝ｻ・､驛｢譎｢・ｽ・､驛｢譎｢・ｽ・ｼ驍ｵ・ｺ繝ｻ・ｨ髯ｷ・ｷ陟包ｽ｡繝ｻ・ｸ・つ驍ｵ・ｺ繝ｻ・ｮcalcGrowth+simulateMatch驛｢・ｧ陝ｶ譏ｶ繝ｻ鬨ｾ蛹・ｽｽ・ｨ      /** 驛｢・ｧ繝ｻ・ｨ驛｢譎｢・ｽ・ｼ驛｢・ｧ繝ｻ・ｹ髯具ｽｻ繝ｻ・､髯橸ｽｳ郢晢ｽｻ 驛｢譏ｴ繝ｻ邵ｺ繝ｻ・ｹ・ｧ繝ｻ・｢髯具ｽｻ繝ｻ・･驛｢・ｧ繝ｻ・ｳ驛｢譎｢・ｽ・ｼ驛｢譏ｶ謔ｪ髢ｻ・ｸ髯溘・繝ｻ繝ｻ蟶晄≧隴∫ｵｶ繝ｻ */     getAceConfig(org, fighter) {       const config = AI_COACH_CONFIG[org.tier] || AI_COACH_CONFIG.B;       const roster = (org.roster || [])         .filter(f => !f.injury)         .sort((a, b) => Engine.util.ov(b) - Engine.util.ov(a));       const rank = roster.findIndex(f => f.id === fighter.id);       if (rank < 0) return config.general; // 髫ｲ・､繝ｻ・ｪ髫ｰ謔溷ｺ翫・・ｸ繝ｻ・ｭ驕ｶ鬆大尅eneral髫ｰ繝ｻ・ｽ・ｱ驍ｵ・ｺ郢晢ｽｻ       if (rank === 0 && config.ace.top1) {         return config.ace.top1;       }       if (rank < config.ace.count && config.ace.top2_3) {         return config.ace.top2_3;       }       if (rank < config.ace.count) {         return config.ace.top1; // A鬩堺ｸ橸ｽ｣・ｹ郢晢ｽｻB鬩堺ｸ橸ｽ｣・ｹ郢晢ｽｻtop1鬮ｫ・ｪ繝ｻ・ｭ髯橸ｽｳ陞｢・ｹ繝ｻ蝣､・ｹ・ｧ繝ｻ・ｨ驛｢譎｢・ｽ・ｼ驛｢・ｧ繝ｻ・ｹ髯ｷ闌ｨ・ｽ・ｨ髯ｷ・ｩ繝ｻ・｡驍ｵ・ｺ繝ｻ・ｫ鬯ｩ蛹・ｽｽ・ｩ鬨ｾ蛹・ｽｽ・ｨ       }       return config.general;     },      /** AI髯昴・・ｽ・ｾ髫ｰ魃会ｽｽ・ｦ驛｢・ｧ繝ｻ・ｫ驛｢譎｢・ｽ・ｼ驛｢譎√・陷・ｽｽ髫ｰ蠕後・ OVR鬮ｴ驢搾ｽｬ・ｬ騾寂悪・ｹ譎擾ｽ｣・ｹ邵ｺ繝ｻ・ｹ譎｢・ｽ・ｪ驛｢譎｢・ｽ・ｳ驛｢・ｧ繝ｻ・ｰ + matchupLog鬯ｲ繝ｻ・ｽ・ｮ髯溯ｶ｣・ｽ・ｦ鬮｢・ｰ郢晢ｽｻ郢晢ｽｻ */     generateAIMatchCard(roster, matchupLog, showCount) {       const available = roster         .filter(f => !f.injury && (f.condition || 70) > 20)         .sort((a, b) => Engine.util.ov(b) - Engine.util.ov(a));       // matchupLog驍ｵ・ｺ陟募ｨｯ譌ｺ驛｢・ｧ陷ｿ・･繝ｻ・ｰ繝ｻ・ｴ髯ｷ・ｷ陋ｹ・ｻ・つ遶擾ｽｫ陝ｲ・ｩ鬮ｴ莉｣繝ｻ髯懃軸・ｨ雋ｻ・ｽ・ｻ繝ｻ・･髯ｷﾂ郢晢ｽｻ郢晢ｽｻ髯ｷ・ｷ陟募ｾ娯ｳ驛｢譎｢・ｽ・ｼ驛｢譎擾ｽｳ・ｨ遶企豪・ｹ譎擾ｽ｣・ｹ郢晢ｽｪ驛｢譎｢・ｽ・ｫ驛｢譏ｴ繝ｻ邵ｺ繝ｻ      const recentThreshold = (showCount || 0) - 3;       const recentPairs = new Set();       if (matchupLog && matchupLog.length > 0) {         matchupLog.filter(e => (e.showCount || 0) >= recentThreshold).forEach(e => {           recentPairs.add(`${Math.min(e.leftId, e.rightId)}_${Math.max(e.leftId, e.rightId)}`);         });       }       const matches = [];       const used = new Set();       for (let i = 0; i < available.length; i++) {         if (used.has(available[i].id)) continue;         let bestJ = -1, bestScore = -Infinity;         for (let j = i + 1; j < available.length; j++) {           if (used.has(available[j].id)) continue;           const ovrDiff = Math.abs(Engine.util.ov(available[i]) - Engine.util.ov(available[j]));           let score = -ovrDiff; // OVR鬮ｴ蜿ｰ・ｻ・｣繝ｻ讓抵ｽｸ・ｺ繝ｻ・ｻ驍ｵ・ｺ繝ｻ・ｩ鬯ｯ・ｮ陋滂ｽ･邵ｺ蟶ｷ・ｹ・ｧ繝ｻ・ｳ驛｢・ｧ繝ｻ・｢           const pairKey = `${Math.min(available[i].id, available[j].id)}_${Math.max(available[i].id, available[j].id)}`;           if (recentPairs.has(pairKey)) score -= 20; // 鬨ｾ・ｶ繝ｻ・ｴ鬮ｴ蜿ｰ・ｻ・｣邵ｺ蜥ｲ・ｹ譎｢・ｽ・ｼ驛｢譎∝ｴ溽ｺ・ｽｾ鬮ｫ髦ｪ繝ｻ郢晢ｽｻ驛｢譎会ｽｿ・ｫ・取刮・ｹ譏ｴ繝ｻ邵ｺ繝ｻ          if (score > bestScore) { bestScore = score; bestJ = j; }         }         if (bestJ >= 0) {           matches.push({ left: available[i], right: available[bestJ] });           used.add(available[i].id);           used.add(available[bestJ].id);         }       }       return matches;     },      // 髫ｨ貂可髫ｨ貂可 Phase 5: AI驛｢・ｧ繝ｻ・ｱ驛｢・ｧ繝ｻ・｢驛｢・ｧ繝ｻ・｢驛｢・ｧ繝ｻ・ｯ驛｢・ｧ繝ｻ・ｷ驛｢譎｢・ｽ・ｧ驛｢譎｢・ｽ・ｳ鬮｢・ｾ繝ｻ・ｪ髯ｷ讎贋ｾ帷ｹ晢ｽｻ鬨ｾ繝ｻ繝ｻ髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可髫ｨ貂可     // 鬩搾ｽｱ繝ｻ・ｴ鬩怜雀・ｸ謨鳴繝ｻ・ｱ驍ｵ・ｺ繝ｻ・ｫ髯橸ｽｳ雋・ｽｯ繝ｻ・｡陟募仰郢ｧ繝ｻﾎ倬Δ・ｧ繝ｻ・｣驛｢・ｧ繝ｻ・｢髣懈瑳蜑後・・ｭ陋滂ｽ･邵ｲ蟶晢ｽｬ繝ｻ・ｽ・ｻ髯溯ｶ｣・ｽ・ｦ驛｢譎｢・ｽ・